def pagina_nueva_vaca(lote: str | None) -> None:
    ctx = f"Lote · {lote}" if lote else "Todos los lotes"
    cabecera("Nueva vaca", ctx,
             "Registrar una nueva vaca en el hato con su foto y datos completos.")

    animales = obtener_animales_ordenados()
    etapas_opts = _get_etapas_options()
    sexos = ["F", "M"]
    lotes_opts = [""] + _get_lotes_options()
    razas = [""] + ["Holstein", "Jersey", "Normanda", "Parda", "Cruzada"]

    with st.form("form_nueva_vaca", clear_on_submit=True):
        col1, col2 = st.columns(2)
        with col1:
            numero = st.text_input("Número visible (chapeta) *", placeholder="Ej. 10131", key="nv_numero")
            nombre = st.text_input("Nombre", key="nv_nombre")
            etapa = st.selectbox("Estado *", etapas_opts,
                                 index=_safe_index(etapas_opts, "TERNERA", "TERNERA"), key="nv_etapa")
            sexo = st.selectbox("Sexo *", ["F", "M"], key="nv_sexo")
            fecha_nac = st.date_input("Fecha de nacimiento", key="nv_fecha_nac")
        with col2:
            raza = st.selectbox("Raza", [""] + ["Holstein", "Jersey", "Normanda", "Parda", "Cruzada"], key="nv_raza")
            lote_sel = st.selectbox("Lote", lotes_opts, key="nv_lote")
            madre = st.selectbox("Madre (opcional)", [""] + obtener_animales_ordenados(), key="nv_madre")
            foto = st.file_uploader("Foto (opcional)", type=["jpg", "jpeg", "png"], key="nv_foto")
            caracteristicas = st.text_area("Características / notas", key="nv_caract")

        enviado = st.form_submit_button("Registrar vaca", type="primary", use_container_width=True)

    if enviado:
        if not numero or not etapa:
            st.error("Número y estado son obligatorios")
        else:
            conn = get_connection()
            try:
                with conn.cursor() as cur:
                    # Verificar que no existe
                    cur.execute("SELECT 1 FROM animales WHERE numero_visible = %s", (numero,))
                    if cur.fetchone():
                        st.error(f"Ya existe un animal con número {numero}")
                        return

                    # Obtener id_lote si se seleccionó
                    id_lote = None
                    if lote_sel:
                        cur.execute("SELECT id_lote FROM lotes WHERE nombre_lote = %s", (lote_sel,))
                        row = cur.fetchone()
                        if row:
                            id_lote = row[0]

                    # Obtener id_madre si se seleccionó
                    id_madre = None
                    if madre:
                        cur.execute("SELECT id_interno FROM animales WHERE numero_visible = %s", (madre,))
                        row = cur.fetchone()
                        if row:
                            id_madre = row[0]

                    # Procesar foto si hay
                    foto_b64 = None
                    if foto:
                        try:
                            img = Image.open(foto)
                            img.thumbnail((800, 800))
                            buf = io.BytesIO()
                            img.save(buf, format="JPEG", quality=85)
                            foto_b64 = base64.b64encode(buf.getvalue()).decode()
                        except Exception as e:
                            st.error(f"Error procesando imagen: {e}")
                            return

                    cur.execute(SQL_INSERT_ANIMAL, (
                        numero, nombre, etapa, id_lote, sexo,
                        fecha_nac if fecha_nac else None, raza or None,
                        caracteristicas or "", id_madre, foto_b64
                    ))
                    nuevo_id = cur.fetchone()[0]
                conn.commit()
                leer_vista.clear()
                st.success(f"Vaca registrada correctamente (N.º {numero})")
                st.rerun()
            except Exception as e:
                conn.rollback()
                st.error(f"Error al registrar: {e}")
            finally:
                conn.close()


def pagina_animales(lote: str | None) -> None:
    ctx = f"Lote · {lote}" if lote else "Todos los lotes"
    cabecera("Animales", ctx, "Catálogo completo del hato. Clic en una tarjeta para ver su ficha.")

    qp = st.query_params
    vaca_sel = qp.get("vaca")
    edit_mode = qp.get("edit") == "1"

    # Filtros
    col_f1, col_f2, col_f3 = st.columns([2, 1, 1])
    with col_f1:
        busqueda = st.text_input("Buscar por número", placeholder="Ej. 1013", key="busca_animal")
    with col_f2:
        mostrar_vendidas = st.checkbox(
            "Mostrar vendidas", value=False, key="ver_vendidas",
            help="Incluye los animales marcados como VENDIDA (solo histórico).")
        df = datos_catalogo(mostrar_vendidas)
        if lote:
            df = df[df["nombre_lote"] == lote]
    with col_f3:
        estados = ["Todos"] + sorted(df["etapa_actual"].dropna().unique().tolist())
        estado_sel = st.selectbox("Estado", estados, key="filtro_estado")

    if busqueda:
        df = df[df["numero_visible"].astype(str).str.contains(busqueda)]
    if estado_sel != "Todos":
        df = df[df["etapa_actual"] == estado_sel]

    # KPIs
    total = len(df)
    con_foto = sum(1 for n in df["numero_visible"] if fotos_de(n))
    criticas = sum(1 for n in df["numero_visible"]
                   if pd.notna(df.loc[df["numero_visible"]==n, "dias_abiertos"].values[0])
                   and df.loc[df["numero_visible"]==n, "dias_abiertos"].values[0] > UMBRAL_DIAS_ABIERTOS)
    kpis(
        {"etiqueta": "Animales", "valor": str(total), "acento": "pasture", "icono": ICONOS["animal"]},
        {"etiqueta": "Con foto", "valor": str(con_foto), "acento": "moss", "icono": ICONOS["leaf"]},
        {"etiqueta": "Por revisar", "valor": str(criticas), "acento": "iron", "icono": ICONOS["clock"]},
    )

# Modo edición de ficha
    if vaca_sel:
        animal = vaca_sel
        if animal in df["numero_visible"].values:
            if qp.get("edit") == "1":
                # Redirigir a página de edición
                st.query_params.update({"page": "editar_animal"})
                st.rerun()
            else:
                # Modo lectura: ficha + botones nativos
                mostrar_ficha(animal)
        else:
            st.warning("Ese animal no coincide con los filtros actuales.")
        return

    # Grid de tarjetas (un solo markdown para que el DOM anide bien)
    cards_html = []
    for _, r in df.iterrows():
        animal = r["numero_visible"]
        fotos = fotos_de(animal)
        thumb = ""
        if fotos:
            try:
                mtime = fotos[0].stat().st_mtime
                thumb = thumb_b64(animal, fotos[0].name, mtime)
            except Exception:
                thumb = ""
        img_html = (
            f'<img src="data:image/jpeg;base64,{thumb}" alt="Foto de {animal}">'
            if thumb else
            '<span class="sin-foto">Sin foto</span>'
        )
        color = color_etapa(r["etapa_actual"])
        cards_html.append(
            f'<a class="ag-card" target="_self" href="?page=animales&vaca={animal}{"" if not lote else f"&lote={lote}"}">'
            f'<div class="ag-card-foto">{img_html}</div>'
            f'<div class="ag-card-cuerpo">'
            f'<div class="ag-card-chapeta">N.º {_html_esc(animal)}</div>'
            f'<span class="ag-card-estado" style="background:{color}">{_html_esc(r["etapa_actual"] or "—")}</span>'
            f'<div class="ag-card-meta">'
            f'Lote {_html_esc(r["nombre_lote"])} · '
            f'{"Peso " + f"{r["peso_actual"]:.0f} kg" if pd.notna(r["peso_actual"]) else "—"}'
            f'{f" · Días {int(r["dias_abiertos"])}" if pd.notna(r["dias_abiertos"]) else ""}'
            f'</div></div></a>'
        )
    st.markdown(
        '<div class="ag-grid">' + "".join(cards_html) + '</div>',
        unsafe_allow_html=True,
    )


PAGINAS = {
    "resumen": pagina_resumen,
    "animales": pagina_animales,
    "dias": pagina_dias_abiertos,
    "peso": pagina_peso,
    "produccion": pagina_produccion,
    "pesaje": pagina_registrar_peso,
    "repro": pagina_registrar_repro,
    "nota": pagina_registrar_nota,
    "editar_animal": pagina_editar_animal,
    "nueva_vaca": pagina_nueva_vaca,
}


def main() -> None:
    st.markdown(FUENTES, unsafe_allow_html=True)
    st.markdown(PWA_META, unsafe_allow_html=True)
    st.markdown(CSS_GLOBAL, unsafe_allow_html=True)

    qp = st.query_params
    page = qp.get("page", "resumen")
    if page not in PAGINAS:
        page = "resumen"
    lote_q = qp.get("lote", "Todos")
    lotes = leer_vista(V_HATO)["lote"].tolist()
    if lote_q != "Todos" and lote_q not in lotes:
        lote_q = "Todos"

    st.markdown(header_html(page, lote_q, lotes), unsafe_allow_html=True)
    components.html(NAV_JS, height=0)
    components.html(PWA_SW_JS, height=0)

    lote = None if lote_q == "Todos" else lote_q
    PAGINAS[page](lote)


if __name__ == "__main__":
    main()
